-- ---------------------------------------------------------------------------
-- 0009 — The 18-stage client lifecycle.
--
-- Derived from docs/DELIVERY-PIPELINE.md (the Excalidraw board's written form).
-- The seven documented stages are the top-level narrative; the eighteen here are
-- the review points inside them, because that is the granularity at which a
-- clock, an owner and a piece of evidence actually attach. Every stage below
-- maps to a documented requirement — the mapping is in
-- docs/REQUIREMENT-TRACEABILITY.md, not invented here.
--
-- Design rules this schema enforces (not decorative columns):
--   * a stage instance cannot exist without a client (lifecycle is per client)
--   * history rows are append-only: there is no UPDATE/DELETE path in the app,
--     and each row records the transition that produced it
--   * evidence is a separate table so "approved" without evidence is visible
--   * rejection carries a reason; resubmission is a new transition row
--   * a clock anchor is expressed by the stage definition, not by handler code
-- ---------------------------------------------------------------------------

-- Stage catalogue: the 18 stages, seeded by the migration so a deployment has
-- them without running a seed script (policy data, like turnover gates).
CREATE TABLE lifecycle_stages (
  id            TEXT PRIMARY KEY,
  key           TEXT NOT NULL UNIQUE,
  position      INTEGER NOT NULL,
  name          TEXT NOT NULL,
  phase         TEXT NOT NULL CHECK (phase IN (
                  'discovery','planning','kickoff','delivery','turnover','post_delivery')),
  intent        TEXT NOT NULL DEFAULT '',
  owner_role    TEXT NOT NULL CHECK (owner_role IN ('admin','lead','member','client')),
  approver_role TEXT NOT NULL CHECK (approver_role IN ('admin','lead','client')),
  required_evidence TEXT NOT NULL DEFAULT '',
  clock_key     TEXT,
  requires_client_signoff INTEGER NOT NULL DEFAULT 0 CHECK (requires_client_signoff IN (0,1)),
  allows_exception INTEGER NOT NULL DEFAULT 1 CHECK (allows_exception IN (0,1))
);
CREATE INDEX idx_lifecycle_stages_pos ON lifecycle_stages(position);

-- Per-client lifecycle state. One row per client per stage.
CREATE TABLE lifecycle_instances (
  id          TEXT PRIMARY KEY,
  client_id   TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  stage_key   TEXT NOT NULL REFERENCES lifecycle_stages(key),
  state       TEXT NOT NULL DEFAULT 'not_started'
              CHECK (state IN ('not_started','in_progress','awaiting_approval','approved','rejected','blocked','skipped')),
  owner_id    TEXT REFERENCES users(id),
  started_at  TEXT,
  submitted_at TEXT,
  decided_at  TEXT,
  due_at      TEXT,
  -- Client-caused waiting is recorded separately from internal delay, so a slow
  -- client never reads as a slow agency and vice versa.
  waiting_on_client_since TEXT,
  client_wait_ms INTEGER NOT NULL DEFAULT 0,
  exception_granted_by TEXT REFERENCES users(id),
  exception_reason TEXT NOT NULL DEFAULT '',
  created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')),
  updated_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')),
  UNIQUE (client_id, stage_key)
);
CREATE INDEX idx_lifecycle_instances_client ON lifecycle_instances(client_id, stage_key);

-- Append-only transition history. Every state change is a row; nothing is
-- mutated in place, so "historical records cannot be silently overwritten" is a
-- property of the schema rather than a promise in a comment.
CREATE TABLE lifecycle_transitions (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  client_id   TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  stage_key   TEXT NOT NULL,
  from_state  TEXT NOT NULL,
  to_state    TEXT NOT NULL,
  actor_id    TEXT REFERENCES users(id),
  actor_role  TEXT NOT NULL DEFAULT '',
  reason      TEXT NOT NULL DEFAULT '',
  note        TEXT NOT NULL DEFAULT '',
  created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS'))
);
CREATE INDEX idx_lifecycle_transitions_client ON lifecycle_transitions(client_id, stage_key, id);

-- Evidence supporting a stage. A stage cannot be approved while its required
-- evidence is missing — that is checked in the transition service, and the rows
-- here are what it checks against.
CREATE TABLE lifecycle_evidence (
  id          TEXT PRIMARY KEY,
  client_id   TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  stage_key   TEXT NOT NULL,
  kind        TEXT NOT NULL CHECK (kind IN (
                'document','link','meeting_note','spec','plan','approval','report','signoff','other')),
  label       TEXT NOT NULL,
  url         TEXT NOT NULL DEFAULT '',
  body        TEXT NOT NULL DEFAULT '',
  supplied_by TEXT REFERENCES users(id),
  created_at  TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS'))
);
CREATE INDEX idx_lifecycle_evidence_client ON lifecycle_evidence(client_id, stage_key);

-- Per-stage permissions beyond the coarse role: which named users may act as
-- owner or approver for a client's lifecycle.
CREATE TABLE lifecycle_assignments (
  id         TEXT PRIMARY KEY,
  client_id  TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  stage_key  TEXT NOT NULL,
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind       TEXT NOT NULL CHECK (kind IN ('owner','approver','watcher')),
  created_at TEXT NOT NULL DEFAULT (to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS')),
  UNIQUE (client_id, stage_key, user_id, kind)
);

